window.CODE = Object.assign(window.CODE || {}, {"ch17/langgraph_mcp.py":"\"\"\"MCP tools inside your own LangGraph graph, with one long-lived session per server.\n\nMultiServerMCPClient.get_tools() opens a short session for each tool call (simple, stateless).\nFor many calls, or servers that keep state, open a session once and load the tools from it.\n\nRun:  python langgraph_mcp.py\n\"\"\"\nimport asyncio\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nfrom langchain_mcp_adapters.client import MultiServerMCPClient  # noqa: E402\nfrom langchain_mcp_adapters.tools import load_mcp_tools  # noqa: E402\nfrom langgraph.graph import START, MessagesState, StateGraph  # noqa: E402\nfrom langgraph.prebuilt import ToolNode, tools_condition  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nCLINIC = {\"clinic\": {\"transport\": \"stdio\", \"command\": sys.executable,\n                     \"args\": [str(HERE.parent / \"ch16\" / \"clinic_server.py\")]}}\n\n\nasync def main():\n    client = MultiServerMCPClient(CLINIC)\n    async with client.session(\"clinic\") as session:            # one session for the whole run\n        tools = await load_mcp_tools(session)\n        model = get_model().bind_tools(tools)\n\n        async def call_model(state: MessagesState) -> dict:\n            return {\"messages\": [await model.ainvoke(state[\"messages\"])]}\n\n        b = StateGraph(MessagesState)\n        b.add_node(\"model\", call_model)\n        b.add_node(\"tools\", ToolNode(tools))\n        b.add_edge(START, \"model\")\n        b.add_conditional_edges(\"model\", tools_condition)\n        b.add_edge(\"tools\", \"model\")\n        graph = b.compile()\n\n        out = await graph.ainvoke({\"messages\": [(\"user\", \"Which days does Dr Khan work?\")]})\n        print(out[\"messages\"][-1].content)\n\n        # Resources and prompts are available too\n        doctors = await client.get_resources(\"clinic\", uris=[\"clinic://doctors\"])\n        print(\"Resource clinic://doctors ->\", \" \".join(doctors[0].as_string().split())[:90], \"...\")\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","ch17/lc_mcp_agent.py":"\"\"\"One agent, two MCP servers: the clinic schedule (Chapter 16) and the appointments database.\n\nlangchain-mcp-adapters turns every MCP tool into a LangChain tool, so create_agent (Chapter 13)\nuses them like any other tool. Adding a third server is one more entry in SERVERS.\n\nRun:  python lc_mcp_agent.py\n\"\"\"\nimport asyncio\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nfrom langchain.agents import create_agent  # noqa: E402\nfrom langchain.agents.middleware import HumanInTheLoopMiddleware, ModelCallLimitMiddleware  # noqa: E402\nfrom langchain_mcp_adapters.client import MultiServerMCPClient  # noqa: E402\nfrom langgraph.checkpoint.memory import InMemorySaver  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nSERVERS = {\n    \"clinic\": {\"transport\": \"stdio\", \"command\": sys.executable,\n               \"args\": [str(HERE.parent / \"ch16\" / \"clinic_server.py\")]},\n    \"appointments_db\": {\"transport\": \"stdio\", \"command\": sys.executable,\n                        \"args\": [str(HERE / \"sqlite_server.py\")]},\n    # A remote server is just a URL:\n    # \"github\": {\"transport\": \"streamable_http\", \"url\": \"https://api.githubcopilot.com/mcp/\",\n    #            \"headers\": {\"Authorization\": \"Bearer <token>\"}},\n}\n\nSYSTEM = (\"You are the City Clinic operations assistant. Use the clinic tools for schedules and the \"\n          \"appointments database (read-only SQL) for statistics. Show the SQL you used.\")\n\n\nasync def main():\n    client = MultiServerMCPClient(SERVERS, tool_name_prefix=True)   # prefix avoids clashes between servers\n    tools = await client.get_tools()\n    print(\"Tools from all servers:\", [t.name for t in tools])\n\n    agent = create_agent(get_model(), tools, system_prompt=SYSTEM, checkpointer=InMemorySaver(), middleware=[\n        ModelCallLimitMiddleware(run_limit=8),\n        HumanInTheLoopMiddleware(interrupt_on={\"clinic_request_appointment\": True}),   # writes need approval\n    ])\n    config = {\"configurable\": {\"thread_id\": \"ops-1\"}}\n    out = await agent.ainvoke({\"messages\": [(\"user\", \"How many no-shows did Dr Rao have, and which days does he work?\")]}, config)\n    for m in out[\"messages\"][1:]:\n        if m.type == \"ai\" and m.tool_calls:\n            print(\"model ->\", [(c[\"name\"], c[\"args\"]) for c in m.tool_calls])\n        elif m.type == \"tool\":\n            print(\"tool  ->\", \" \".join(m.text.split())[:110])\n        else:\n            print(\"answer->\", m.content)\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","ch17/ready_made_servers.json":"{\n  \"mcpServers\": {\n    \"filesystem\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@modelcontextprotocol/server-filesystem\", \"/home/you/clinic-reports\"]\n    },\n    \"playwright\": {\n      \"command\": \"npx\",\n      \"args\": [\"@playwright/mcp@latest\"]\n    },\n    \"github\": {\n      \"command\": \"docker\",\n      \"args\": [\"run\", \"-i\", \"--rm\", \"-e\", \"GITHUB_PERSONAL_ACCESS_TOKEN\", \"ghcr.io/github/github-mcp-server\"],\n      \"env\": { \"GITHUB_PERSONAL_ACCESS_TOKEN\": \"<fine-grained token, read-only, one repo>\" }\n    },\n    \"appointments-db\": {\n      \"command\": \"/full/path/to/venv/bin/python\",\n      \"args\": [\"/full/path/to/code-samples/ch17/sqlite_server.py\"]\n    }\n  }\n}\n","ch17/sqlite_server.py":"\"\"\"A read-only MCP server for the clinic appointments database.\n\nAny MCP host (Claude Desktop, VS Code, Claude Code, your agents) can now ask questions about\nappointments. Safety is enforced here, in the server, so every client gets the same rules:\n  - the database file is opened read-only (mode=ro)\n  - only a single SELECT is accepted, with a row cap and a time limit\n  - only the tables in ALLOWED_TABLES are visible\n\nRun:  python sqlite_server.py --init     (create the demo database once)\n      python sqlite_server.py            (stdio server)\n\"\"\"\nimport random\nimport sqlite3\nimport sys\nimport time\nfrom pathlib import Path\n\nfrom mcp.server.fastmcp import FastMCP\nfrom mcp.types import ToolAnnotations\n\nDB = Path(__file__).with_name(\"clinic.db\")\nALLOWED_TABLES = {\"appointments\"}\nMAX_ROWS, MAX_SECONDS = 100, 2.0\nREAD_ONLY = ToolAnnotations(readOnlyHint=True, openWorldHint=False)\n\nmcp = FastMCP(\"Clinic appointments (read-only)\", log_level=\"WARNING\")\n\n\ndef make_db() -> None:\n    \"\"\"Made-up appointment data; no real patients.\"\"\"\n    DB.unlink(missing_ok=True)\n    con = sqlite3.connect(DB)\n    con.execute(\"CREATE TABLE appointments (id INTEGER PRIMARY KEY, doctor TEXT, department TEXT, day TEXT, status TEXT)\")\n    rng = random.Random(7)\n    docs = [(\"Dr Mehta\", \"cardiology\", [\"Mon\", \"Wed\"]), (\"Dr Rao\", \"cardiology\", [\"Thu\", \"Fri\"]),\n            (\"Dr Iyer\", \"orthopaedics\", [\"Tue\", \"Thu\"]), (\"Dr Khan\", \"paediatrics\", [\"Mon\", \"Tue\", \"Fri\"])]\n    for i in range(1, 201):\n        doc, dept, days = rng.choice(docs)\n        status = rng.choices([\"completed\", \"no_show\", \"cancelled\", \"booked\"], [70, 12, 8, 10])[0]\n        con.execute(\"INSERT INTO appointments VALUES (?,?,?,?,?)\", (i, doc, dept, rng.choice(days), status))\n    con.commit()\n    con.close()\n\n\ndef connect():\n    con = sqlite3.connect(f\"file:{DB}?mode=ro\", uri=True)\n    deadline = time.monotonic() + MAX_SECONDS\n    con.set_progress_handler(lambda: 1 if time.monotonic() > deadline else 0, 10_000)   # stop runaway queries\n    return con\n\n\n@mcp.tool(annotations=READ_ONLY)\ndef list_tables() -> list[str]:\n    \"\"\"List the tables you may query.\"\"\"\n    return sorted(ALLOWED_TABLES)\n\n\n@mcp.tool(annotations=READ_ONLY)\ndef describe_table(table: str) -> list[dict]:\n    \"\"\"Show the columns of one table. Call this before writing SQL.\"\"\"\n    if table not in ALLOWED_TABLES:\n        raise ValueError(f\"Unknown table. Allowed: {sorted(ALLOWED_TABLES)}\")\n    with connect() as con:\n        return [{\"column\": r[1], \"type\": r[2]} for r in con.execute(f\"PRAGMA table_info({table})\")]\n\n\n@mcp.tool(annotations=READ_ONLY)\ndef query(sql: str) -> dict:\n    \"\"\"Run ONE read-only SQLite SELECT and return up to 100 rows.\"\"\"\n    q = sql.strip().rstrip(\";\")\n    if not q.lower().startswith(\"select\") or \";\" in q:\n        raise ValueError(\"Only a single SELECT statement is allowed.\")\n    try:\n        with connect() as con:\n            cur = con.execute(q)\n            cols = [d[0] for d in cur.description]\n            rows = cur.fetchmany(MAX_ROWS + 1)\n    except sqlite3.OperationalError as exc:\n        if \"interrupted\" in str(exc):\n            raise ValueError(f\"Query took longer than {MAX_SECONDS} s. Add WHERE filters or GROUP BY.\") from exc\n        raise ValueError(f\"SQL error: {exc}. Check names with describe_table.\") from exc\n    return {\"columns\": cols, \"rows\": rows[:MAX_ROWS], \"truncated\": len(rows) > MAX_ROWS}\n\n\n@mcp.resource(\"clinic-db://schema\", mime_type=\"text/plain\")\ndef schema() -> str:\n    \"\"\"The CREATE TABLE statements, for attaching as context.\"\"\"\n    with connect() as con:\n        return \"\\n\".join(r[0] for r in con.execute(\"SELECT sql FROM sqlite_master WHERE type='table'\"))\n\n\nif __name__ == \"__main__\":\n    if \"--init\" in sys.argv:\n        make_db()\n        print(\"Created\", DB)\n    else:\n        if not DB.exists():\n            make_db()\n        mcp.run()\n","common/lc_models.py":"\"\"\"One place to create LangChain chat models and embeddings for every Part C chapter.\n\nLangChain hides the provider differences, so switching OpenAI <-> Anthropic is one line:\n\n    init_chat_model(\"openai:gpt-4.1-mini\")     or     init_chat_model(\"anthropic:claude-haiku-5-5\")\n\nThis helper reads the same .env settings as llm.py (PROVIDER, OPENAI_MODEL, ANTHROPIC_MODEL).\n\n    from lc_models import get_model, get_embeddings\n    model = get_model()                  # a LangChain chat model for your PROVIDER\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\nfrom langchain.chat_models import init_chat_model\nfrom langchain_core.embeddings import Embeddings\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\n\n\ndef get_model(provider: str | None = None, temperature: float = 0, **kwargs):\n    \"\"\"A chat model with sensible production defaults: a timeout and automatic retries.\"\"\"\n    provider = provider or PROVIDER\n    return init_chat_model(f\"{provider}:{MODELS[provider]}\", temperature=temperature,\n                           timeout=float(os.getenv(\"LLM_TIMEOUT\", \"30\")),\n                           max_retries=int(os.getenv(\"LLM_RETRIES\", \"2\")), **kwargs)\n\n\nclass CourseEmbeddings(Embeddings):\n    \"\"\"Wraps llm.embed() (Chapter 6) so LangChain vector stores can use it.\n    EMBEDDINGS=openai uses text-embedding-3-small; EMBEDDINGS=local uses a free local model.\"\"\"\n\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\n        from llm import embed\n        return embed(texts)\n\n    def embed_query(self, text: str) -> list[float]:\n        return self.embed_documents([text])[0]\n\n\ndef get_embeddings() -> Embeddings:\n    return CourseEmbeddings()\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
